def maxChunksToSortedAny(arr):
    n = len(arr)
    suf = [0] * n
    suf[-1] = arr[-1]
    for i in range(n - 2, -1, -1):
        suf[i] = min(arr[i], suf[i + 1])
    chunks = 1
    mx = arr[0]
    for i in range(n - 1):
        mx = max(mx, arr[i])
        if mx <= suf[i + 1]:
            chunks += 1
    return chunks
